def create_initial_versions(apps, schema_editor):
    """
    // Give every program's existing curriculum mappings an approved version 1.
    // The initial version has no effective-from term so it applies to every
    // term until an admin clones and approves a successor.
    """
    Curriculum = apps.get_model('core', 'Curriculum')
    CurriculumVersion = apps.get_model('core', 'CurriculumVersion')
    Program = apps.get_model('core', 'Program')

    programs_with_entries = (
        Curriculum.objects.filter(version__isnull=True)
        .values_list('program_id', flat=True)
        .distinct()
    )
    program_ids = set(programs_with_entries)

    for program_id in program_ids:
        version = CurriculumVersion.objects.create(
            program_id=program_id,
            version_number=1,
            status='APPROVED',
            notes='Initial curriculum imported from existing program mappings.',
        )
        Curriculum.objects.filter(
            program_id=program_id,
            version__isnull=True,
        ).update(version=version)

    # Programs without mappings still get their first version so the matrix
    # editor opens in a predictable approved-then-draft state.
    for program_id in Program.objects.values_list('pk', flat=True):
        if program_id in program_ids:
            continue
        CurriculumVersion.objects.create(
            program_id=program_id,
            version_number=1,
            status='APPROVED',
            notes='Initial empty curriculum.',
        )


def remove_initial_versions(apps, schema_editor):
    Curriculum = apps.get_model('core', 'Curriculum')
    CurriculumVersion = apps.get_model('core', 'CurriculumVersion')

    version_ids = list(CurriculumVersion.objects.values_list('pk', flat=True))
    Curriculum.objects.filter(version_id__in=version_ids).update(version=None)
    CurriculumVersion.objects.filter(pk__in=version_ids).delete()


